'use strict';
const app=document.getElementById('app'),dialog=document.getElementById('dialog');
let library=[],activeId=null,view='request',saved=true,modal=null,pendingCsv=null,lastDeleted=null;
let previewQuantity=120;
let writeQueue=Promise.resolve(),saveSequence=0,savePending=0;
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>library.find(w=>w.id===activeId);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const money=(v,c)=>{if(v===null||v===undefined)return '—';const [a,b='00']=String(v).split('.');return `${h(c)} ${a.replace(/\B(?=(\d{3})+(?!\d))/g,',')}.${b.padEnd(2,'0')}`};
const approved=w=>w.history.findLast(r=>r.revision===w.revision&&r.fingerprint===QL.fingerprint(w));
const uid=prefix=>prefix+'-'+crypto.randomUUID().slice(0,12);
function notify(text,error=false){const t=document.getElementById('toast');t.textContent=text;t.className=error?'error':'';t.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.hidden=true,4800);}
const saveLabel=()=>savePending?'Saving on this device…':saved?'Saved on this device':'Not saved — export a backup';
function updateSaveIndicator(){const el=document.querySelector('.save-state');if(el){el.textContent=saveLabel();el.className='save-state '+(!saved&&!savePending?'failed':'');}}
async function persist(w,{refresh=true}={}){const i=library.findIndex(x=>x.id===w.id);if(i<0)library.push(w);else library[i]=w;const sequence=++saveSequence,snapshot=structuredClone(w);savePending++;saved=false;if(refresh)render();else updateSaveIndicator();const write=writeQueue.catch(()=>{}).then(()=>QuoteStore.put(snapshot));writeQueue=write;try{await write;if(sequence===saveSequence)saved=true;}catch(e){if(sequence===saveSequence)saved=false;notify(e.message,true);throw e;}finally{savePending--;updateSaveIndicator();}}
async function change(fn,options){const w=structuredClone(current());fn(w);w.revision++;const check=QL.validateWorkspace(w);if(!check.valid)throw Error(check.errors.join('\n'));await persist(w,options);}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function workspaceBackup(){const w=current();download('quotelens-'+w.id+'.json',JSON.stringify(w,null,2));notify('Workspace backup exported. Keep it to move or restore your data.');}
function field(label,name,value='',type='text',extra='',help=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${h(value)}" ${extra}>${help?`<small>${help}</small>`:''}</label>`;}
function selectField(label,name,options,value,help=''){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>`<option value="${h(o[0])}" ${String(value)===String(o[0])?'selected':''}>${h(o[1])}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</label>`;}
function openModal(title,body,button,context){modal=context;dialog.innerHTML=`<form id="modal-form"><div class="dialog-head"><h2>${title}</h2><button type="button" class="btn quiet small" data-action="dismiss" aria-label="Close dialog">✕</button></div><div class="dialog-body">${body}<div class="dialog-error" role="alert"></div></div><div class="dialog-foot"><button type="button" class="btn" data-action="dismiss">${button?'Cancel':'Close'}</button>${button?`<button type="submit" class="btn primary">${button}</button>`:''}</div></form>`;dialog.showModal();}
function render(){const w=current(),a=w?QL.analyze(w):null,r=w?approved(w):null;
app.innerHTML=`<div class="layout ${w?'has-workspace':'is-home'}">
<header class="site-header"><a class="brand" href="./" aria-label="QuoteLens home"><img src="icon.svg" alt="">QuoteLens<span class="brand-caption">Supplier quote comparison</span></a><nav class="site-nav" aria-label="Product links"><a href="guide.html">Guide</a><a href="case-study.html">Case study</a><a href="https://github.com/builtbyhuy/quotelens-review-workbench" target="_blank" rel="noopener">GitHub ↗</a></nav><button class="btn primary" data-action="new">Compare my quotes <span aria-hidden="true">＋</span></button></header>
<div class="app-frame"><aside class="workbench-rail" aria-label="Workbench navigation"><div class="rail-section"><span class="eyebrow">Your comparisons</span><button class="rail-link ${w?'':'current'}" data-action="home">Overview <b aria-hidden="true">↗</b></button><button class="rail-link" data-action="library">Saved workspaces <b class="rail-count">${library.length}</b></button><button class="rail-link" data-action="restore">Import backup <b aria-hidden="true">↓</b></button></div>${w?`<div class="rail-context"><span class="eyebrow">Current request</span><strong>${h(w.title)}</strong><dl><div><dt>Currency</dt><dd>${h(w.currency)}</dd></div><div><dt>Review date</dt><dd>${h(w.date)}</dd></div><div><dt>Revision</dt><dd>${w.revision}</dd></div></dl></div>`:''}<div class="rail-storage"><span class="storage-dot" aria-hidden="true"></span><strong>Private to this browser</strong><p>Your quotes are not uploaded.<br>Export a backup to keep a copy.</p><a href="guide.html#privacy">Storage & limitations ↗</a></div></aside>
<main class="main"><div class="content">${w?`<div class="workspace-topline"><button class="text-link" data-action="home">← All comparisons</button><span class="save-state ${!saved&&!savePending?'failed':''}">${saveLabel()}</span></div>${renderWorkspace(w,a,r)}`:renderWelcome()}<footer class="footer-line"><span>QuoteLens · Independent product by Huy</span><nav aria-label="Project details"><a href="case-study.html">Case study</a><a href="https://github.com/builtbyhuy/quotelens-review-workbench" target="_blank" rel="noopener">GitHub ↗</a><a href="guide.html#privacy">Data & limitations</a></nav></footer></div></main></div></div>`;
}
// This first-use comparison runs through the same calculation engine as saved work.
// It is never persisted until the visitor explicitly opens it as a workspace.
function previewWorkspace(quantity=previewQuantity){
  const w=sampleWorkspace();
  w.title='Example · Compare two supplier quotes';
  w.request=w.request.slice(0,1);
  w.request[0].quantity=quantity;
  w.offers=w.offers.filter(o=>o.itemId==='bolts');
  QL.analyze(w).items.forEach(i=>{if(i.cheapest)w.selections[i.request.id]=i.cheapest.offer.id;});
  return w;
}
function previewAnalysis(){const w=previewWorkspace(),a=QL.analyze(w);return {w,item:a.items[0]};}
function renderPreview(){
  const {w,item}=previewAnalysis();
  const winner=item.offers.find(o=>o.offer.id===w.selections.bolts);
  return `<div class="quick-table" role="table" aria-label="Costs of two fictional supplier quotes"><div class="quick-columns" role="row"><span role="columnheader">Supplier quote</span><span role="columnheader">Unit price</span><span role="columnheader">What you buy</span><span role="columnheader">Order total</span></div>${item.offers.map(o=>`<div class="quick-offer ${o===winner?'is-lowest':''}" role="row"><div class="quick-supplier" role="rowheader"><span class="supplier-mark" aria-hidden="true">${o.offer.supplier==='Oak Supply'?'O':'B'}</span><div><strong>${h(o.offer.supplier)}</strong><span>${o.offer.packSize} bolts / pack · $${o.offer.packPrice}</span></div></div><div class="quick-unit" role="cell"><small>Unit price</small><strong>$${o.offer.supplier==='Oak Supply'?'0.18':'0.22'}</strong>${o.offer.supplier==='Oak Supply'?'<span class="unit-note">Cheaper per bolt</span>':''}</div><div class="quick-packs" role="cell"><small>What you buy</small><strong>${o.packs} ${o.packs===1?'pack':'packs'} · ${o.units} bolts</strong><span>${o.overage} extra · $${o.offer.deliveryFee} delivery</span></div><div class="quick-total" role="cell"><small>Order total</small><strong>$${o.total}</strong><span>${o===winner?'✓ Lowest order cost':'Whole packs + delivery'}</span></div></div>`).join('')}</div><div class="comparison-answer"><span class="answer-check" aria-hidden="true">✓</span><p><strong>${h(winner.offer.supplier)} costs less for ${previewQuantity} bolts.</strong><span>${winner.offer.supplier==='Oak Supply'?'Fewer whole packs and delivery make the difference.':`Oak's lower unit price means buying ${item.offers[0].units} bolts, plus delivery.`}</span></p><button class="btn" data-action="preview-open">Open this comparison <span aria-hidden="true">→</span></button></div>`;
}
function renderWelcome(){return `<section class="comparison-start" aria-labelledby="comparison-title"><div class="start-heading"><div><span class="product-purpose">For purchasing & operations</span><h1 id="comparison-title">Compare supplier quotes.<br>See the real cost.</h1><p>Pack sizes, minimum orders and delivery can change which offer wins.</p></div><div class="start-own"><button class="btn primary" data-action="new">Compare my own quotes <span aria-hidden="true">→</span></button><span>No account. Your data stays in this browser.</span></div></div><div class="comparison-surface"><div class="comparison-toolbar"><div class="comparison-subject"><span class="part-sketch" aria-hidden="true"><svg viewBox="0 0 52 52"><path d="m13 13 8-5 9 5v9l-8 5-9-5zM22 27l17 17m-11-15-4 4m9 1-4 4m9 1-4 4M14 13l8 5 8-5m-8 5v9"/></svg></span><div><span class="example-label">Interactive example · fictional quotes</span><h2>Workshop bolts</h2></div></div><div class="quantity-control"><label for="preview-quantity">How many do you need?</label><div><input id="preview-quantity" type="number" min="1" max="300" step="1" value="${previewQuantity}" aria-describedby="preview-quantity-help"><span>bolts</span></div><button class="btn small preview-preset" data-action="preview-quantity" data-quantity="${previewQuantity===120?100:120}">Try ${previewQuantity===120?100:120} bolts <span aria-hidden="true">↗</span></button></div></div><p class="preview-error" id="preview-error" role="alert" hidden></p><p class="comparison-hint" id="preview-quantity-help">Change the quantity. The lowest unit price is not always the lowest order cost.</p><div id="quick-comparison" aria-live="polite">${renderPreview()}</div></div><div class="start-details"><span>Use your own CSV or enter quotes by hand.</span><span>Keep the original source with every reviewed decision.</span><a href="guide.html">How it works ↗</a></div></section>
<section class="workfiles" aria-labelledby="workfiles-title"><div class="section-intro"><div><h2 id="workfiles-title">Your comparisons <span class="saved-count">${library.length}</span></h2><p>Saved on this device.</p></div><div class="actions"><button class="text-link" data-action="library">View all</button><button class="text-link" data-action="restore">Import backup ↓</button></div></div>${library.length?`<div class="recent-list">${library.slice(0,4).map(x=>`<button class="project-button" data-action="open" data-id="${h(x.id)}"><span class="project-file" aria-hidden="true">▤</span><strong>${h(x.title)}</strong><span>${x.request.length} items · ${x.offers.length} offers</span><span class="project-currency">${h(x.currency)} <b aria-hidden="true">→</b></span></button>`).join('')}</div>`:`<div class="file-empty"><div class="file-outline" aria-hidden="true">▤</div><div><strong>Your first comparison belongs here.</strong><p>Start with what you need to buy, then add supplier quotes.</p></div><button class="btn" data-action="new">New comparison <span aria-hidden="true">＋</span></button></div>`}</section>`;}
function updatePreview(quantity){
  const parsed=Number(quantity),input=document.getElementById('preview-quantity');
  const error=document.getElementById('preview-error');
  if(!Number.isInteger(parsed)||parsed<1||parsed>300){input?.setCustomValidity('Enter a whole quantity from 1 to 300 for this example.');input?.setAttribute('aria-invalid','true');if(error){error.hidden=false;error.textContent='Use a whole quantity from 1 to 300 in this example. Your own comparisons allow larger requests.';}return false;}
  input?.removeAttribute('aria-invalid');if(error)error.hidden=true;
  input?.setCustomValidity('');previewQuantity=parsed;
  const result=document.getElementById('quick-comparison');if(result)result.innerHTML=renderPreview();
  if(input)input.value=String(parsed);
  const toggle=document.querySelector('[data-action="preview-quantity"]');
  if(toggle){toggle.dataset.quantity=String(parsed===120?100:120);toggle.innerHTML=`Try ${parsed===120?100:120} bolts <span aria-hidden="true">↗</span>`;}
  return true;
}

function renderWorkspace(w,a,r){return `<section class="workspace-heading"><div><span class="workspace-purpose">Supplier quote comparison</span><h1>${h(w.title)}</h1><p class="muted">Review date ${h(w.date)} · ${h(w.currency)} · Revision ${w.revision} &nbsp; <span class="status ${r?'approved':a.complete?'':'warning'}">${r?'Approved revision':a.complete?'Ready for review':'In progress'}</span></p></div><div class="workspace-actions"><button class="btn small" data-action="settings">Workspace settings</button><button class="btn small" data-action="backup">Export backup</button><button class="btn quiet small" data-action="delete">Delete</button></div></section>${!saved&&!savePending?'<div class="notice error">This browser could not save the latest changes. Export a backup before closing this tab.</div>':''}<nav class="tabs" aria-label="Workspace sections">${[['request','Purchase request',w.request.length],['offers','Supplier offers',w.offers.length],['decision','Compare & decide',a.items.filter(i=>i.selected?.eligible).length],['history','Decision history',w.history.length]].map(([id,name,n])=>`<button class="tab ${view===id?'active':''}" data-action="view" data-view="${id}" ${view===id?'aria-current="page"':''}>${name}<span>${n}</span></button>`).join('')}</nav><div class="workspace-view">${view==='request'?renderRequest(w):view==='offers'?renderOffers(w,a):view==='history'?renderHistory(w,r):renderDecision(w,a,r)}</div>`;}
function renderRequest(w){return `<div class="section-head"><div><h2>What do you need to buy?</h2><p>Set quantities and matching item IDs before bringing in supplier offers.</p></div><button class="btn primary" data-action="add-item">Add an item</button></div>${!w.request.length?`<div class="empty"><div class="empty-graphic" aria-hidden="true"><i></i><i></i><i></i></div><h2>Your request starts here.</h2><p>Add the first item, its quantity and unit. You can set a maximum lead time when delivery matters.</p><button class="btn primary" data-action="add-item">Add your first item</button></div>`:`<div class="panel"><div class="request-summary"><div class="summary-pair"><span class="big">${w.request.length}</span><span class="label">request items</span></div><span class="small muted">One currency per workspace. Quantities are whole units.</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Item</th><th>Matching ID</th><th>Required quantity</th><th>Maximum lead time</th><th>Actions</th></tr></thead><tbody>${w.request.map((i,n)=>`<tr><td><div class="item-title"><span class="item-icon" aria-hidden="true">${n+1}</span><strong>${h(i.label)}</strong></div></td><td>${h(i.id)}</td><td class="numeric">${i.quantity.toLocaleString()} ${h(i.unit)}</td><td>${i.maxLeadDays===null?'No limit':i.maxLeadDays+' days'}</td><td><div class="actions"><button class="btn small" data-action="edit-item" data-id="${h(i.id)}">Edit</button><button class="btn quiet small" data-action="remove-item" data-id="${h(i.id)}">Remove</button></div></td></tr>`).join('')}</tbody></table></div></div><div class="help-box"><div><h3>Ready to collect offers?</h3><p>The CSV template includes your item IDs. Send or fill it, then import the completed offers.</p></div><div class="actions"><button class="btn small" data-action="template">Download offer template</button><button class="btn small primary" data-action="view" data-view="offers">Add supplier offers</button></div></div>`}`;}
function renderOffers(w,a){return `<div class="section-head"><div><h2>Compare your supplier offers.</h2><p>Map a CSV or enter an offer. Delivery fees apply to each offer line; shared order freight and taxes are outside this version.</p></div><div class="actions"><button class="btn" data-action="template" ${!w.request.length?'disabled':''}>CSV template</button><button class="btn" data-action="import" ${!w.request.length?'disabled':''}>Import offers CSV</button><button class="btn primary" data-action="add-offer" ${!w.request.length?'disabled':''}>Add offer</button></div></div>${!w.request.length?'<div class="empty"><h2>Create your purchase request first.</h2><p>Offers need an item ID to match against.</p><button class="btn primary" data-action="view" data-view="request">Go to purchase request</button></div>':!w.offers.length?'<div class="empty"><h2>Every comparison starts with an offer.</h2><p>Use your own CSV columns or add an offer by hand. You can include stock, expiry and lead time, or leave them explicitly unknown.</p><div class="actions"><button class="btn primary" data-action="add-offer">Add your first offer</button><button class="btn" data-action="import">Import offers CSV</button></div></div>':a.items.map(i=>`<section class="offer-group"><div class="group-head"><div><h3>${h(i.request.label)}</h3><p class="muted">Need ${i.request.quantity} ${h(i.request.unit)} · matching ID ${h(i.request.id)}</p></div><button class="btn small" data-action="add-offer" data-item="${h(i.request.id)}">Add offer for this item</button></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Supplier / quote</th><th>Pack price / size</th><th>Packs to buy</th><th>Purchase cost</th><th>Checks</th><th>Source</th><th></th></tr></thead><tbody>${i.offers.map(o=>`<tr class="${o.eligible?'':'blocked-row'}"><td><span class="offer-name">${h(o.offer.supplier)}</span><span class="cell-sub">${h(o.offer.quoteId||'No quote ID')}</span>${w.selections[i.request.id]===o.offer.id?'<span class="selected-mark">Selected</span>':''}</td><td class="numeric">${money(o.offer.packPrice,o.offer.currency)}<span class="cell-sub">${o.offer.packSize} ${h(i.request.unit)} per pack</span></td><td class="numeric">${o.packs??'—'}<span class="cell-sub">${o.overage===null?'':`${o.overage} extra units`}</span></td><td class="numeric"><strong>${money(o.total,w.currency)}</strong><span class="cell-sub">Includes ${money(o.deliveryCost,w.currency)} line delivery</span></td><td><span class="status ${o.eligible?(o.warnings.length?'warning':''):'error'}">${o.eligible?'Eligible':'Blocked'}</span>${o.reasons.length?`<span class="reason">${o.reasons.map(h).join('<br>')}</span>`:''}${o.warnings.length?`<span class="warn-text">${o.warnings.map(h).join('<br>')}</span>`:''}</td><td><button class="btn small" data-action="source" data-id="${h(o.offer.id)}">Inspect source</button><span class="cell-sub">${h(o.offer.source.filename)}${o.offer.source.line?' · row '+o.offer.source.line:''}</span></td><td><button class="btn quiet small" data-action="remove-offer" data-id="${h(o.offer.id)}" aria-label="Remove offer from ${h(o.offer.supplier)}">✕</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">No offers for this item.</td></tr>'}</tbody></table></div></div></section>`).join('')}${w.offers.some(o=>!w.request.some(i=>i.id===o.itemId))?'<div class="notice error">Some imported item IDs do not match this request. Use the source CSV to correct them or clear offers and import again.</div>':''}${w.offers.length?'<div class="actions"><button class="btn primary" data-action="view" data-view="decision">Compare & decide</button><button class="btn quiet" data-action="clear-offers">Clear all offers</button></div>':''}`;}
function renderDecision(w,a,r){if(!w.request.length)return '<div class="empty"><h2>Build a request to start comparing.</h2><p>The decision will show the actual cost of the whole packs you choose.</p><button class="btn primary" data-action="view" data-view="request">Create purchase request</button></div>';return `<div class="section-head"><div><h2>Choose suppliers. Review the real total.</h2><p>Lowest eligible cost is a starting point. Record why the selected supplier makes sense for each item.</p></div><button class="btn" data-action="lowest">Select lowest eligible costs</button></div>${!a.complete?`<div class="notice">A complete selection is needed before approval.${a.issues.length?'<ul>'+a.issues.map(x=>'<li>'+h(x)+'</li>').join('')+'</ul>':''}</div>`:''}${w.history.length&&!r?'<div class="notice">This workspace changed after a previous approval. The old receipt is preserved in history; review the current revision again.</div>':''}${r?`<div class="notice success">This exact revision was approved on ${h(new Date(r.approvedAt).toLocaleString())}. Export the receipt or comparison below.</div>`:''}<div class="decision-layout"><div class="panel">${a.items.map(i=>`<section class="decision-item"><div class="decision-title"><div><h3>${h(i.request.label)}</h3><span class="cell-sub">${i.request.quantity} ${h(i.request.unit)} requested · ${h(i.request.id)}</span></div><strong class="numeric">${money(i.selected?.eligible?i.selected.total:null,w.currency)}</strong></div><label for="select-${h(i.request.id)}">Selected supplier</label><select id="select-${h(i.request.id)}" data-select="${h(i.request.id)}"><option value="">Choose an eligible offer</option>${i.offers.map(o=>`<option value="${h(o.offer.id)}" ${w.selections[i.request.id]===o.offer.id?'selected':''} ${o.eligible?'':'disabled'}>${h(o.offer.supplier)} · ${money(o.total,w.currency)}${o.eligible?'':' · BLOCKED'}</option>`).join('')}</select>${i.selected?.eligible?`<div class="decision-calc"><span><strong>${i.selected.packs} packs</strong> × ${i.selected.offer.packSize} units = ${i.selected.units} units</span><span>${money(i.selected.goodsCost,w.currency)} goods + ${money(i.selected.deliveryCost,w.currency)} line delivery</span><button class="btn quiet small" data-action="source" data-id="${h(i.selected.offer.id)}">Inspect source</button></div>${i.selected.warnings.length?`<span class="warn-text">${i.selected.warnings.map(h).join(' · ')}</span>`:''}`:''}<label for="reason-${h(i.request.id)}">Why this selection? (optional)</label><textarea id="reason-${h(i.request.id)}" data-note="${h(i.request.id)}" maxlength="4000" placeholder="Price, delivery, specification or another reason">${h(w.notes[i.request.id]||'')}</textarea><button type="button" class="btn small" data-action="save-note" data-id="${h(i.request.id)}">Save note</button></section>`).join('')}</div><aside class="decision-summary"><div class="summary-left"><span class="summary-label">Selected purchase ${a.complete?'total':'subtotal'}</span><div class="amount">${money(a.total,w.currency)}</div><p>${a.items.filter(i=>i.selected?.eligible).length} of ${w.request.length} items selected<br>Whole packs + per-line delivery fees</p></div><hr><div><button class="btn primary" data-action="approve" ${a.complete?'':'disabled'}>${r?'View approved receipt':'Review this revision'}</button><button class="btn" data-action="decision-csv" ${r?'':'disabled'}>Export approved CSV</button><button class="btn" data-action="receipt" ${r?'':'disabled'}>Export receipt JSON</button></div><p class="summary-note">No purchase order is placed. Taxes and shared supplier-order freight are not included. Missing commercial facts stay flagged for review.</p></aside></div>`;}
function renderHistory(w,r){return `<div class="section-head"><div><h2>A record of what was reviewed.</h2><p>Past receipts retain their original inputs. A changed workspace needs a new approval.</p></div></div>${w.history.length?[...w.history].reverse().map(x=>`<section class="history-card"><div><h3>Revision ${x.revision} · ${money(x.total,x.currency)} &nbsp; <span class="status ${x===r?'approved':''}">${x===r?'Current':'Historical'}</span></h3><p>${h(new Date(x.approvedAt).toLocaleString())} · ${x.lines.length} selected items</p></div><div class="actions"><button class="btn small" data-action="history-view" data-id="${h(x.id)}">View receipt</button><button class="btn small" data-action="history-export" data-id="${h(x.id)}">Export JSON</button></div></section>`).join(''):'<div class="empty"><h2>No decisions approved yet.</h2><p>Choose an eligible offer for each item, then review the current revision. The resulting receipt will appear here.</p><button class="btn primary" data-action="view" data-view="decision">Compare & decide</button></div>'}`;}
function showWorkspaceForm(w){openModal(w?'Comparison settings':'Start a quote comparison',`<p>Name what you are buying and choose one currency. Next, add the items you need and your supplier quotes.</p><div class="form-grid">${field('Comparison name','title',w?.title||'','text','required maxlength="160" placeholder="e.g. Workshop supplies — October"')}${selectField('Currency','currency',['USD','EUR','GBP','VND'].map(x=>[x,x]),w?.currency||'USD','One currency per workspace. No exchange rates are inferred.')}${field('Review date','date',w?.date||today(),'date','required')}</div>`,w?'Save settings':'Create comparison',{type:w?'settings':'new'});}
function showItemForm(item){const w=current();openModal(item?'Edit request item':'Add a request item',`<div class="form-grid">${field('Item name','label',item?.label||'','text','required maxlength="160"')}${field('Matching item ID','id',item?.id||'item-'+(w.request.length+1),'text','required maxlength="128"','Use this ID in your supplier CSV. Changing it also updates existing matched offers.')}${field('Required quantity','quantity',item?.quantity||1,'number','required min="1" max="1000000000" step="1"')}${field('Unit','unit',item?.unit||'ea','text','required maxlength="32"','Examples: ea, boxes, metres. Quantities are whole units.')}${field('Maximum lead time (days)','maxLeadDays',item?.maxLeadDays??'','number','min="0" max="36500" step="1"','Leave blank when you have no delivery constraint.')}</div>`,'Save item',{type:'item',id:item?.id});}
function showOfferForm(itemId){const w=current();openModal('Add a supplier offer',`<p>Pack price is the price of one pack. A delivery fee applies to this line only. Leave stock, lead time or expiry blank when the supplier has not supplied them.</p><div class="form-grid">${selectField('Request item','itemId',w.request.map(i=>[i.id,i.label+' ('+i.id+')']),itemId||w.request[0]?.id)}${field('Supplier','supplier','','text','required maxlength="160"')}${field('Quote ID','quoteId','','text','maxlength="128"')}${field('Units per pack','packSize',1,'number','required min="1" max="1000000000" step="1"')}${field('Price per pack ('+h(w.currency)+')','packPrice','','text','required inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" placeholder="18.50"')}${field('Minimum packs to buy','minPacks',1,'number','required min="1" max="1000000000" step="1"')}${field('Available packs','stockPacks','','number','min="0" max="1000000000" step="1"')}${field('Lead time (days)','leadDays','','number','min="0" max="36500" step="1"')}${field('Offer valid through','validUntil','','date')}${field('Delivery fee for this line','deliveryFee','0.00','text','required inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?"')}</div>`,'Add offer',{type:'offer'});}
const csvFields=[['itemId','Item ID *'],['supplier','Supplier *'],['packSize','Units per pack *'],['packPrice','Price per pack *'],['quoteId','Quote ID'],['minPacks','Minimum packs'],['stockPacks','Available packs'],['leadDays','Lead time (days)'],['validUntil','Valid through'],['currency','Currency'],['deliveryFee','Delivery fee per line']];
const aliases={itemId:['itemid','item_id','sku','productid','product_id','item'],supplier:['supplier','vendor','suppliername','vendor_name'],packSize:['packsize','pack_size','unitsperpack','packqty'],packPrice:['packprice','pack_price','price','priceperpack'],quoteId:['quoteid','quote_id','quote'],minPacks:['minpacks','min_packs','moq'],stockPacks:['stockpacks','stock_packs','availablepacks','stock'],leadDays:['leaddays','lead_days','leadtime'],validUntil:['validuntil','valid_until','expiry','expires'],currency:['currency','ccy'],deliveryFee:['deliveryfee','delivery_fee','freight','shipping']};
function showMapping(text,filename){const p=QL.parseCsv(text);if(p.errors.length)throw Error(p.errors.join('\n'));if(!p.rows.length)throw Error('The CSV has a header but no offer rows.');pendingCsv={text,filename};const map=csvFields.map(([key,label])=>{const found=p.headers.find(x=>aliases[key].includes(x.toLowerCase().replace(/\s/g,'')));return selectField(label,key,[['','Not supplied'],...p.headers.map(x=>[x,x])],found||'');}).join('');openModal('Match your CSV columns',`<p>${h(filename)} · ${p.rows.length} rows. Import appends offers; your existing offers stay in place. Item IDs must match your purchase request. Prices use a dot decimal and no currency symbols.</p><div class="mapping-list">${map}</div><p style="margin-top:18px">Defaults: minimum 1 pack, no line delivery fee, and workspace currency. Missing stock, lead time and expiry stay unverified. A malformed row stops the import so nothing is silently skipped.</p>`,'Import offers',{type:'import'});}
function showSource(offer){openModal('The source behind this offer',`<p><strong>${h(offer.supplier)}</strong> · ${h(offer.source.filename)}${offer.source.line?' · physical row '+offer.source.line:''}</p><pre class="source-pre">${h(JSON.stringify(offer.source.raw,null,2))}</pre><p style="margin-top:15px">Original source values are preserved. Missing fields are not evidence of stock, lead time or validity.</p>`,null,{type:'source'});}
function showReceipt(r){openModal('Approved decision · revision '+r.revision,`<p>${h(r.title)} · approved ${h(new Date(r.approvedAt).toLocaleString())}</p><div class="receipt-total"><strong>${money(r.total,r.currency)}</strong><span>${r.lines.length} selected items · no purchase order placed</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Item / supplier</th><th>Purchase</th><th>Total</th></tr></thead><tbody>${r.lines.map(l=>`<tr><td><strong>${h(l.itemLabel)}</strong><span class="cell-sub">${h(l.supplier)} · ${h(l.source.filename)}${l.source.line?' row '+l.source.line:''}</span><span class="cell-sub">${h(l.reason||'No reviewer note')}</span></td><td>${l.packs} packs / ${l.units} units</td><td>${money(l.total,r.currency)}</td></tr>`).join('')}</tbody></table></div><p style="margin-top:17px">This is a local review record with its full input snapshot. It is not a signed purchase order or a tamper-proof certificate. Export it from Decision history.</p>`,null,{type:'receipt'});}
function sampleWorkspace(){const w=QL.newWorkspace({title:'Example · Workshop supplies',date:today(),currency:'USD'});w.request=[{id:'bolts',label:'Workshop bolts',quantity:120,unit:'ea',maxLeadDays:7},{id:'seals',label:'Replacement seals',quantity:37,unit:'ea',maxLeadDays:null}];const src={filename:'Fictional example',line:null,raw:{note:'Synthetic supplier and offer for the editable tour.'}};w.offers=[{id:uid('offer'),itemId:'bolts',supplier:'Oak Supply',quoteId:'OAK-01',packSize:100,packPrice:'18.00',minPacks:1,stockPacks:20,leadDays:3,validUntil:'',currency:'USD',deliveryFee:'4.00',source:structuredClone(src)},{id:uid('offer'),itemId:'bolts',supplier:'Birch Parts',quoteId:'BIR-02',packSize:10,packPrice:'2.20',minPacks:1,stockPacks:30,leadDays:5,validUntil:'',currency:'USD',deliveryFee:'1.00',source:structuredClone(src)},{id:uid('offer'),itemId:'seals',supplier:'Cedar Industrial',quoteId:'CED-03',packSize:10,packPrice:'10.00',minPacks:1,stockPacks:20,leadDays:null,validUntil:'',currency:'USD',deliveryFee:'1.00',source:structuredClone(src)},{id:uid('offer'),itemId:'seals',supplier:'Oak Supply',quoteId:'OAK-04',packSize:3,packPrice:'3.00',minPacks:1,stockPacks:20,leadDays:3,validUntil:'',currency:'USD',deliveryFee:'5.00',source:structuredClone(src)}];return w;}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,w=current();try{
 if(action==='dismiss'){dialog.close();return;}
 if(action==='new'){showWorkspaceForm();return;}
 if(action==='home'){activeId=null;render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(action==='library'){openModal('Your comparisons',`${library.length?`<div class="project-list">${library.map(x=>`<button type="button" class="project-button" data-action="open" data-id="${h(x.id)}"><strong>${h(x.title)}</strong><span>${x.request.length} items · ${x.offers.length} offers · ${h(x.currency)}</span></button>`).join('')}</div>`:'<p>No workspaces are saved on this device yet. Create one from the workbench, or import a JSON backup to continue an existing request.</p>'}<button type="button" class="btn" data-action="restore">Import workspace backup</button>`,null,{type:'library'});return;}
 if(action==='preview-quantity'){updatePreview(b.dataset.quantity);return;}
 if(action==='preview-open'){const input=document.getElementById('preview-quantity');if(!updatePreview(input?.value??previewQuantity))return;const n=previewWorkspace();activeId=n.id;view='decision';await persist(n);window.scrollTo({top:0,behavior:'instant'});notify('Fictional comparison opened. Replace or edit any item and offer.');return;}
 if(action==='example'){const n=sampleWorkspace();activeId=n.id;view='offers';await persist(n);notify('Fictional example opened. Every item and offer is editable.');return;}
 if(action==='open'){activeId=b.dataset.id;if(dialog.open)dialog.close();render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(action==='view'){view=b.dataset.view;render();const heading=app.querySelector('.workspace-heading h1');if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});heading.scrollIntoView({block:'start',behavior:'instant'});}return;}
 if(action==='settings'){showWorkspaceForm(w);return;}
 if(action==='backup'){workspaceBackup();return;}
 if(action==='restore'){if(dialog.open)dialog.close();document.getElementById('backup-file').click();return;}
 if(action==='add-item'){showItemForm();return;}
 if(action==='edit-item'){showItemForm(w.request.find(i=>i.id===b.dataset.id));return;}
 if(action==='remove-item'){const i=w.request.find(i=>i.id===b.dataset.id);openModal('Remove '+h(i.label)+'?',`<p>This also removes its offers and current selection. Historical approval snapshots stay in Decision history.</p>`,'Remove item',{type:'remove-item',id:i.id});return;}
 if(action==='add-offer'){showOfferForm(b.dataset.item);return;}
 if(action==='remove-offer'){await change(n=>{n.offers=n.offers.filter(o=>o.id!==b.dataset.id);for(const k of Object.keys(n.selections))if(n.selections[k]===b.dataset.id)delete n.selections[k];});notify('Offer removed. Review any changed decision again.');return;}
 if(action==='source'){showSource(w.offers.find(o=>o.id===b.dataset.id));return;}
 if(action==='import'){document.getElementById('csv-file').click();return;}
 if(action==='clear-offers'){openModal('Clear all offers?',`<p>Your request and historical receipts stay. Export a workspace backup first if you want a copy of the current offers.</p>`,'Clear offers',{type:'clear-offers'});return;}
 if(action==='delete'){openModal('Delete this workspace?',`<p>The workspace will be removed from this device. Export a backup first to keep it. You can restore the last deleted workspace during this tab session.</p>`,'Delete workspace',{type:'delete'});return;}
 if(action==='undo-delete'){if(lastDeleted){activeId=lastDeleted.id;await persist(lastDeleted);lastDeleted=null;dialog.close();}return;}
 if(action==='template'){const esc=v=>{let s=String(v);if(/^[\s\u0000-\u001f]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const rows=[['item_id','item_label','supplier','quote_id','pack_size','pack_price','min_packs','stock_packs','lead_days','valid_until','currency','delivery_fee'],...w.request.map(i=>[i.id,i.label,'','','1','','1','','','',w.currency,'0.00'])];download('quotelens-offer-template.csv',rows.map(row=>row.map(esc).join(',')).join('\r\n'),'text/csv;charset=utf-8');return;}
 if(action==='save-note'){const id=b.dataset.id,value=document.getElementById('reason-'+id).value;if((current().notes[id]||'')!==value)await change(n=>{n.notes[id]=value;});else{render();await writeQueue;}notify('Selection note saved.');return;}
 if(action==='lowest'){const a=QL.analyze(w);await change(n=>{for(const i of a.items){if(i.cheapest)n.selections[i.request.id]=i.cheapest.offer.id;else delete n.selections[i.request.id];}});notify('Lowest eligible line costs selected. Review unverified commercial facts before approval.');return;}
 if(action==='approve'){const r=approved(w);if(r){showReceipt(r);return;}const a=QL.analyze(w);if(!a.complete)throw Error('Choose an eligible offer for every request item.');const selectedWarnings=a.items.flatMap(i=>i.selected.warnings.map(x=>i.request.label+' / '+i.selected.offer.supplier+': '+x));openModal('Review revision '+w.revision,`<p>Confirm your selections and the unknown facts below. Approval records this exact snapshot; it sends no order or supplier message.</p><div class="receipt-total"><strong>${money(a.total,w.currency)}</strong><span>${a.items.length} selected items</span></div>${selectedWarnings.length?`<div class="notice">Unverified facts<ul>${selectedWarnings.map(x=>'<li>'+h(x)+'</li>').join('')}</ul></div>`:''}<label class="check-line"><input name="ack" type="checkbox" required><span>I reviewed the selected offers, source values and any unverified facts. I understand taxes and shared order freight are excluded.</span></label>`,'Approve revision '+w.revision,{type:'approve',revision:w.revision,fingerprint:QL.fingerprint(w)});return;}
 if(action==='decision-csv'){if(!approved(w))throw Error('Approve the current revision before exporting an approved decision.');download('quotelens-decision-r'+w.revision+'.csv',QL.exportDecisionCsv(w),'text/csv;charset=utf-8');return;}
 if(action==='receipt'){const r=approved(w);if(!r)throw Error('This revision needs approval.');download('quotelens-receipt-r'+r.revision+'.json',JSON.stringify(r,null,2));return;}
 if(action==='history-view'){showReceipt(w.history.find(r=>r.id===b.dataset.id));return;}
 if(action==='history-export'){const r=w.history.find(r=>r.id===b.dataset.id);download('quotelens-receipt-r'+r.revision+'.json',JSON.stringify(r,null,2));}
}catch(e){notify(e.message,true);}});
document.addEventListener('change',async ev=>{try{
 if(ev.target.dataset.select){const itemId=ev.target.dataset.select,offerId=ev.target.value;await change(w=>{if(offerId)w.selections[itemId]=offerId;else delete w.selections[itemId];});return;}
 if(ev.target.dataset.note){const id=ev.target.dataset.note,value=ev.target.value;if((current().notes[id]||'')===value)return;await change(w=>{w.notes[id]=value;},{refresh:false});return;}
 if(ev.target.id==='csv-file'){const f=ev.target.files[0];ev.target.value='';if(!f)return;if(f.size>QL.LIMITS.csvChars)throw Error('CSV is too large. Use a file up to 2 MB.');showMapping(await f.text(),f.name);return;}
 if(ev.target.id==='backup-file'){const f=ev.target.files[0];ev.target.value='';if(!f)return;if(f.size>QL.LIMITS.backupChars)throw Error('Workspace backup is too large (maximum 8 MB).');let w;try{w=JSON.parse(await f.text());}catch{throw Error('This file is not valid JSON. Choose a QuoteLens workspace backup.');}const result=QL.validateWorkspace(w);if(!result.valid)throw Error('Backup rejected:\n'+result.errors.slice(0,8).join('\n'));if(library.some(x=>x.id===w.id)){openModal('Replace the saved workspace?',`<p>This backup has the same workspace ID as one on this device. Export the current version first if you want both. Restoring replaces it with the backup contents.</p>`,'Restore backup',{type:'restore',workspace:w});return;}activeId=w.id;view='request';await persist(w);notify('Workspace restored from the validated backup.');}
}catch(e){notify(e.message,true);}});
dialog.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target;if(!form.reportValidity())return;const f=new FormData(form),v=k=>String(f.get(k)||'').trim(),num=k=>v(k)===''?null:Number(v(k));try{
 if(modal.type==='new'){const w=QL.newWorkspace({title:v('title'),date:v('date'),currency:v('currency')});activeId=w.id;view='request';await persist(w);}
 if(modal.type==='settings')await change(w=>{w.title=v('title');w.date=v('date');w.currency=v('currency');});
 if(modal.type==='item'){const item={id:v('id'),label:v('label'),quantity:num('quantity'),unit:v('unit'),maxLeadDays:num('maxLeadDays')};await change(w=>{if(w.request.some(i=>i.id===item.id&&i.id!==modal.id))throw Error('That matching item ID already exists. Choose a unique ID.');if(modal.id){const index=w.request.findIndex(i=>i.id===modal.id);w.request[index]=item;if(modal.id!==item.id){for(const o of w.offers)if(o.itemId===modal.id)o.itemId=item.id;if(w.selections[modal.id]){w.selections[item.id]=w.selections[modal.id];delete w.selections[modal.id];}if(w.notes[modal.id]){w.notes[item.id]=w.notes[modal.id];delete w.notes[modal.id];}}}else w.request.push(item);});}
 if(modal.type==='offer'){const w=current();const offer={id:uid('offer'),itemId:v('itemId'),supplier:v('supplier'),quoteId:v('quoteId'),packSize:num('packSize'),packPrice:v('packPrice'),minPacks:num('minPacks'),stockPacks:num('stockPacks'),leadDays:num('leadDays'),validUntil:v('validUntil'),currency:w.currency,deliveryFee:v('deliveryFee'),source:{filename:'Manual entry',line:null,raw:{}}};offer.source.raw={...Object.fromEntries(f.entries()),currency:w.currency};await change(n=>n.offers.push(offer));view='offers';render();}
 if(modal.type==='import'){const map=Object.fromEntries(f.entries());map._currency=current().currency;for(const key of ['itemId','supplier','packSize','packPrice'])if(!map[key])throw Error('Map the required field: '+key);const result=QL.importCsv(pendingCsv.text,map,pendingCsv.filename);if(result.errors.length)throw Error(result.errors.slice(0,12).join('\n'));if(!result.offers.length)throw Error('No offers were found.');await change(w=>w.offers.push(...result.offers));view='offers';render();notify(result.offers.length+' offers imported with their original source values.');pendingCsv=null;}
 if(modal.type==='remove-item')await change(w=>{w.request=w.request.filter(i=>i.id!==modal.id);w.offers=w.offers.filter(o=>o.itemId!==modal.id);delete w.selections[modal.id];delete w.notes[modal.id];});
 if(modal.type==='clear-offers')await change(w=>{w.offers=[];w.selections={};});
 if(modal.type==='approve'){const w=current();if(w.revision!==modal.revision||QL.fingerprint(w)!==modal.fingerprint)throw Error('The workspace changed. Close this dialog and review the current revision.');if(!f.get('ack'))throw Error('Confirm that you reviewed the selections.');let r=approved(w);if(!r){r=QL.createReceipt(w,new Date().toISOString());const n=structuredClone(w);n.history.push(r);if(n.history.length>QL.LIMITS.history)throw Error('This workspace has reached its receipt limit. Export a backup and start a new workspace.');await persist(n);}notify('Revision approved. No order or supplier message was sent.');}
 if(modal.type==='restore'){activeId=modal.workspace.id;view='request';await persist(modal.workspace);notify('Backup restored.');}
 if(modal.type==='delete'){const w=current();await QuoteStore.remove(w.id);lastDeleted=w;library=library.filter(x=>x.id!==w.id);activeId=library[0]?.id||null;render();dialog.close();openModal('Workspace deleted',`<p>The last deleted workspace can be restored until you close this tab.</p><button type="button" class="btn" data-action="undo-delete">Restore deleted workspace</button>`,null,{type:'deleted'});return;}
 dialog.close();
}catch(e){dialog.querySelector('.dialog-error').textContent=e.message;}});
document.addEventListener('input',event=>{if(event.target.id==='preview-quantity')updatePreview(event.target.value);});
(async()=>{try{if(!globalThis.QL)throw Error('The calculation engine did not load. Reload the page to try again.');library=await QuoteStore.all();library=library.filter(w=>QL.validateWorkspace(w).valid);activeId=null;render();}catch(e){saved=false;render();notify(e.message,true);}})();
